class BytesIOCopy(io.BufferedRandom):
    """Patch a real (file descriptor backed) binary stream to let the
    written data be copied to another stream. Backed by a real OS-level
    temporary file (rather than :class:`io.BytesIO`) so that it exposes a
    working ``fileno()``, allowing code under test to pass ``sys.stdout``
    or ``sys.stderr`` to APIs such as :func:`subprocess.run` that require a
    real file descriptor.

    .. versionadded:: 8.2
    """

    def __init__(self, copy_to: io.BytesIO) -> None:
        self._tmp = tempfile.TemporaryFile()
        super().__init__(self._tmp)  # type: ignore[arg-type]
        self.copy_to = copy_to

    def flush(self) -> None:
        super().flush()
        self.copy_to.flush()

    def write(self, b: ReadableBuffer) -> int:
        self.copy_to.write(b)
        return super().write(b)

    def getvalue(self) -> bytes:
        pos = self.tell()
        self.seek(0)
        try:
            return self.read()
        finally:
            self.seek(pos)

